type SessionUser = { id: string; role: "member" | "admin" } | null;
type AuthDecision =
  | { status: 200; userId: string }
  | { status: 401 }
  | { status: 403 };

function authorizeWrite(user: SessionUser): AuthDecision {
  if (user === null) {
    return { status: 401 };
  }
  if (user.role !== "admin") {
    return { status: 403 };
  }
  return { status: 200, userId: user.id };
}
